// POST /functions/v1/push — wiring only; the logic is in handler.ts (tested in handler.test.ts).
// Deploy WITH JWT verification (verify_jwt = true).
// Secrets: VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY (base64url, generated by the owner, see docs/PUSH_SETUP.md),
// VAPID_SUBJECT (a contact URL or mailto: chosen by the owner). Missing → 503 push_not_configured.
import { createClient } from 'npm:@supabase/supabase-js@2.48.1';
import { parseVapidKeys } from '../_shared/webpush.ts';
import { createPushHandler } from './handler.ts';

const url = Deno.env.get('SUPABASE_URL')!;
// Service role: ONLY for the push RPCs (the caller's own devices, by user id from the verified JWT).
const admin = createClient(url, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, { auth: { persistSession: false } });
const keys = parseVapidKeys(Deno.env.get('VAPID_PUBLIC_KEY'), Deno.env.get('VAPID_PRIVATE_KEY'));
const subject = Deno.env.get('VAPID_SUBJECT')?.trim();
if (!keys || !subject) console.warn('push: VAPID keys or subject not configured; answering push_not_configured');

Deno.serve(createPushHandler({
  async getUser(req) {
    const userClient = createClient(url, Deno.env.get('SUPABASE_ANON_KEY')!, {
      global: { headers: { Authorization: req.headers.get('Authorization') ?? '' } }, auth: { persistSession: false },
    });
    const { data, error } = await userClient.auth.getUser();
    return error || !data?.user ? null : { id: data.user.id };
  },
  vapid: keys && subject ? { keys, subject } : null,
  store: {
    async targets(userId) {
      const { data, error } = await admin.rpc('mvl_push_targets', { p_users: [userId] });
      if (error) throw new Error('targets failed');
      return (data ?? []) as { id: string; endpoint: string; p256dh: string; auth: string }[];
    },
    async record(id, ok, gone) {
      await admin.rpc('mvl_push_record_result', { p_subscription: id, p_ok: ok, p_gone: gone });
    },
  },
  fetch: (...a) => fetch(...a),
}));
